// changes. It is re-mounted for each claim opened, so it starts filled with that claim's values.
// Its template select adds a DRAFT claim from a sheet's template (its amount and note as they stand
// then, no date) by the same rules; a refusal shows in the form's error.
function ClaimForm({ sheetId, personId, editing }: { sheetId: string; personId: number; editing?: Claim }) {
  const [, setEditing] = useEditingClaim();
  const [amount, setAmount] = useState(editing?.amount ?? '');
  const [date, setDate] = useState(editing?.date ?? '');
  const [note, setNote] = useState(editing?.note ?? '');
  const [corrects, setCorrects] = useState(editing?.corrects ?? '');
  const [ref, setRef] = useState(editing?.ref ?? '');
  const [tags, setTags] = useState(editing?.tags.join(', ') ?? '');
  const [user] = useUser();
  const queryClient = useQueryClient();
  const sheet = `/api/sheets/${encodeURIComponent(sheetId)}`;
  const save = useMutation({
    mutationKey: claimSaveKey(sheetId),
    mutationFn: async (body: ClaimBody) => {
      if (body.amount.trim() === '') throw new Error('Enter an amount');
      if (!AMOUNT.test(body.amount.trim())) throw new Error('An amount is a number with up to two decimals');
      // `by` is the signed-in user the change is recorded against.
      const sent = { ...body, by: user ?? '' };
      return editing
        ? putJson<Claim>(`${sheet}/claims/${editing.id}`, sent)
        : postJson<Claim>(`${sheet}/people/${personId}/claims`, sent);
    },
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
      if (editing) {
        setEditing(undefined);
      } else {
        setAmount('');
        setDate('');
        setNote('');
        setCorrects('');
        setRef('');
        setTags('');
      }
    },
  });
  const templates = useTemplates(sheetId);
  const [template, setTemplate] = useState('');
  const [newDate, setNewDate] = useState('');
  const [inlineAmount, setInlineAmount] = useState('');
  const [commentText, setCommentText] = useState('');
  const [lineLabel, setLineLabel] = useState('');
  const [lineQty, setLineQty] = useState('');
  const [lineUnit, setLineUnit] = useState('');
  const people = usePeople(sheetId);
  const [editingId, setEditing] = useEditingClaim();
  const periods = usePeriods(sheetId);
  const roles = useRoles(sheetId);
  const delegations = useDelegations(sheetId);
  const sheetToday = useSheetToday(sheetId);
  // An edit the screen can already tell is refused shows its refusal at once, before any request: the claim form must
  // not be taken for its editor. The server refuses the same edits (and any it alone can tell).
  const [refused, setRefused] = useState<string>();
  // A viewer's edit is refused too, but its editor opens (to be cancelled), as for a lock another user holds.
  // One a steward's delegation holds on the sheet's today acts as a steward, as the server decides.
  const viewer = () => {
    const assigned = roles.data ?? [];
    const steward = (name: string) => assigned.some((r) => r.user === name && r.role === 'steward');
    const today = sheetToday.data?.today;
    const acting = today !== undefined && (delegations.data ?? []).some((d) =>
      d.user === user && steward(d.by) && d.from <= today && today <= d.to);
    return !acting && assigned.some((r) => r.user === user && r.role === 'viewer');
  };

