test("forward only rates scenario 2", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-20");
  await ui.setSetting(pg_uma, "clerk-limit", "1.50");
  await ui.setSetting(pg_uma, "floor", "2.00");
  await ui.setSetting(pg_uma, "terms", "7");
  await ui.setSetting(pg_uma, "late-pct", "5.00");
  await ui.setSetting(pg_uma, "proof-threshold", "3.00");
  expect(await ui.setRole(pg_uma, "wes", "viewer")).toBe(true);
  await ui.setSetting(pg_uma, "grace-A", "5");
  expect(await ui.addVoidReason(pg_uma, "dup")).toBe(true);
  expect(await ui.addVoidReason(pg_uma, "error")).toBe(true);
  await ui.loadSheet(pg_uma, `${sheet}-p`);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "5.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "33.33"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "33.33"})).toBe(true);
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "C"}));
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "C"}));
  await ui.loadSheet(pg_uma, sheet);
  await ui.setSetting(pg_uma, "parent", `${sheet}-p`);
  await ui.setSetting(pg_uma, "pot", "100.00");
  await ui.setSetting(pg_uma, "fiscal-start-month", "4");
  await ui.setSetting(pg_uma, "alert-threshold", "1.00");
  expect(await ui.setSettingDated(pg_uma, "rounding", "half-up", "2026-03-01", "half-up")).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "5.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "20.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "20.00", "from": "2026-03-01"})).toBe(true);
  expect(await ui.generatePeriods(pg_uma, "2026-02-01", "2026-04-30")).toBe(3);
  expect(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B", "terms": "3", "contact": " Ada@x "})).toBeNull();
  expect(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "A", "terms": "3"})).toBeNull();
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "B", "terms": "20", "tags": "b, a"}));
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "5.00", "from": "2026-04-04"})).toBe(true);
  await ui.sortBy(pg_uma, "grade");
  await ui.expectAuditView(pg_uma, "Ada", [
    `ROLLUP sheet=${sheet} by=uma person=Ada claimed=0.00 due-total=0.00 overdue-total=0.00`,
    `PERSON_ADDED sheet=${sheet} by=uma name=Ada grade=B terms=20`
  ]);
  await ui.sortBy(pg_uma, "due-total");
  expect(await ui.periodAction(pg_uma, "2026-03", "close")).toBe(true);
  expect(await ui.retire(pg_uma, p_ada, "2026-04-02")).toBe(true);
  await ui.showRetired(pg_uma, true);
  const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "0.04", "note": "n", "tags": "a, B"}));

